  IEnumerator Resolve(){long earned=0;for(int beat=1;beat<=result.Beats;beat++){if(!skipRequested)sound.Cue("beat");foreach(var e in result.Events.Where(e=>e.Beat==beat)){earned+=e.Credits;if(e.Credits>0&&!skipRequested){sound.Cue("cash");var n=run.Board.Nodes.Find(z=>z.Id==e.Source);if(n!=null){GameFeel.Burst(38+(n.X+.5f)*644/run.Board.Width,310+(n.Y+.4f)*644/run.Board.Height,FlatUI.Hex("#FFD572"),12,2);var t=Studio.Label(grid,"+"+e.Credits,(n.X+.5f)*720f/run.Board.Width-80,(n.Y+.12f)*1280f/run.Board.Height,160,110,24,Studio.Accent,TextAlignmentOptions.Center,true);if(!data.Profile.ReducedMotion)t.gameObject.AddComponent<FloatingNumber>();}}if(e.Reason=="shipment"&&!skipRequested)Pulse(e);}score.text="$"+earned.ToString("N0")+" · "+beat+"/"+result.Beats;var scorePulse=score.GetComponent<HudPulse>()??score.gameObject.AddComponent<HudPulse>();scorePulse.Punch();if(skipRequested)yield return null;else yield return new WaitForSeconds(TradingStepSeconds);}busy=false;sound.Cue(result.Credits>=run.Mission.Target?"win":"loss");Result();}
  void Pulse(FlowEvent e){if(data.Profile.ReducedMotion)return;var a=run.Board.Nodes.Find(n=>n.Id==e.Source);var b=run.Board.Nodes.Find(n=>n.Id==e.Target);if(a==null||b==null)return;var dot=FlatUI.Rect(root,"Flow",38+(a.X+.5f)*644f/run.Board.Width-10,310+(a.Y+.5f)*644f/run.Board.Height-10,20,20);var token=dot.gameObject.AddComponent<ResourceToken>();token.Kind=e.Kind;token.raycastTarget=false;if(run.Board.RulesVersion==1)StartCoroutine(TravelRoad(dot,a,b,e.TravelSteps*TradingStepSeconds));else StartCoroutine(Travel(dot,b.X-a.X,b.Y-a.Y));}
  IEnumerator Travel(RectTransform dot,int dx,int dy){var start=dot.anchoredPosition;float time=0;while(time<.28f){time+=Time.deltaTime;dot.anchoredPosition=start+new Vector2(dx*grid.rect.width/run.Board.Width,-dy*grid.rect.height/run.Board.Height)*Mathf.Clamp01(time/.28f);yield return null;}Destroy(dot.gameObject);}
