  void Help(){if(empireMode&&empire?.Snapshot.City!=null){WorldHelp();return;}var m=Studio.Modal(root,"HOW YOUR CITY WORKS",Settings);Studio.Label(m,"Plan a neighborhood that trades well.\n\nRESIDENTS visit shops. A normal journey takes one simulated minute per block. They can travel across the city; a shorter walk leaves more time to shop.\n\nFARMS harvest stock. Shops use stock to serve customers. The first café starts with 48 servings; later farms replenish it.\n\nCAFE: one customer + one stock makes an $80 sale. It can serve two per minute. Both must arrive first.\n\nROUTES lets you choose a destination. Automatic routing tries nearby compatible buildings with room. Rotate is not a road rule.\n\nA trading day lasts 24 simulated minutes. Forecast and undo are free. Sales are the puzzle score; saved rewards are separate. Permanent homes acquired in the empire earn rent.",44,220,632,850,25);Studio.Button(m,"LET'S BUILD",44,1090,632,135,Board,true);}
